def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform full rows and columns mark the dividers between tiles.
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_div_color = grid[div_rows[0]][0] if div_rows else None
    col_div_color = grid[0][div_cols[0]] if div_cols else None

    row_cuts = [-1] + div_rows + [h]
    col_cuts = [-1] + div_cols + [w]
    row_blocks = [(row_cuts[i] + 1, row_cuts[i + 1])
                  for i in range(len(row_cuts) - 1)]
    col_blocks = [(col_cuts[i] + 1, col_cuts[i + 1])
                  for i in range(len(col_cuts) - 1)]

    # The most common color outside the dividers is the tile background.
    counts = {}
    for r in range(h):
        if r in div_rows:
            continue
        for c in range(w):
            if c not in div_cols:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    background = max(counts, key=counts.get)

    # Find the block containing the tile pattern, rather than empty background.
    blocks = [(r0, r1, c0, c1)
              for r0, r1 in row_blocks for c0, c1 in col_blocks]
    sr, er, sc, ec = max(
        blocks,
        key=lambda b: sum(grid[r][c] != background
                          for r in range(b[0], b[1])
                          for c in range(b[2], b[3]))
    )
    tile = [grid[r][sc:ec] for r in range(sr, er)]

    out = [[background] * w for _ in range(h)]
    for r in div_rows:
        out[r] = [grid[r][c] for c in range(w)]
    for c in div_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = tile[r - r0][c - c0]
    return out
